from vs import corpus,ivtff
from collections import Counter,defaultdict
import random,math,json
CHARS='acdefgiklmnopqrsy';K=18; A=18

def cls(w):return CHARS.index(w[0]) if w[0] in CHARS else 17
def good(w):return bool(w) and w.isascii() and w.islower() and w.isalpha() and not ivtff.uncertain(w)
def pos(i):return 0 if i==1 else 1 if i<=3 else 2 if i<=6 else 3
def length(n):return 0 if n<=6 else 1 if n<=10 else 2
def rows(pages):
 out=[]
 for p in pages:
  for l in p.lines:
   if l.unit!='P':continue
   for i in range(1,len(l.words)):
    a,b=l.words[i-1:i+1]
    if good(a) and good(b):out.append((p.id,l.id,i,len(l.words),l.para_start,cls(a),cls(b)))
 return out

def fit(rs):
 cnt=Counter();ctx=Counter();tot=Counter();ctot=Counter()
 for p,l,i,n,pf,a,b in rs:
  z=(pos(i),length(n),pf);cnt[z,b]+=1;tot[z]+=1;ctx[z,a,b]+=1;ctot[z,a]+=1
 def loggain(r):
  p,l,i,n,pf,a,b=r;z=(pos(i),length(n),pf);base=(cnt[z,b]+1)/(tot[z]+K);alt=(ctx[z,a,b]+A*base)/(ctot[z,a]+A);return math.log(alt/base)
 return loggain

def assess(rs,model,shuffle=False):
 v=[model(r) for r in rs];gp=defaultdict(list)
 for r,x in zip(rs,v):gp[r[0]].append(x)
 keys=sorted(gp);rng=random.Random(31001);bs=[]
 for i in range(2000):
  picked=[rng.choice(keys) for k in keys];bs.append(sum(sum(gp[k]) for k in picked)/sum(len(gp[k]) for k in picked))
 bs.sort();out={'tokens':len(rs),'folios':len(keys),'gain':sum(v)/len(v),'eval_folio_boot_95':[bs[49],bs[1949]]}
 if shuffle:
  batches=defaultdict(list)
  for j,r in enumerate(rs):batches[(r[0],r[3],r[4],r[2])].append(j)
  movable=[indices for indices in batches.values() if len(set(rs[i][5] for i in indices))>1]
  sh=[]
  for seed in range(99):
   rng=random.Random(seed+6000);a=[r[5] for r in rs]
   for g in batches.values():
    vals=[a[i] for i in g];rng.shuffle(vals)
    for i,x in zip(g,vals):a[i]=x
   sh.append(sum(model(r[:5]+(a[j],r[6])) for j,r in enumerate(rs))/len(rs))
  out.update({'shuffle_min':min(sh),'shuffle_max':max(sh),'shuffle_mean':sum(sh)/len(sh),'shuffles_above_equal':sum(x>=out['gain'] for x in sh),'movable_cells':len(movable),'moved_row_fraction':sum(len(g) for g in movable)/len(rs)})
 return out
zltrain=corpus.split_pages('practice','zl')[0];ittrain=corpus.split_pages('practice','it')[0];ids=[p.id for p in zltrain];assert len(set(ids))==len(ids)
# Reserve every fifth training folio in original manuscript order.
test_ids={p for i,p in enumerate(ids) if i%5==4};train_ids=set(ids)-test_ids
assert train_ids.isdisjoint(test_ids)
pages={t:[p for p in ps if p.id in test_ids] for t,ps in [('zl',zltrain),('it',ittrain)]}
lines={t:{(p.id,l.id):len(l.words) for p in pages[t] for l in p.lines if l.unit=='P'} for t in pages};matched={k for k,n in lines['zl'].items() if lines['it'].get(k)==n}
allrows={t:rows(pages[t]) for t in pages};rm={t:{(r[0],r[1],r[2]):r for r in allrows[t] if (r[0],r[1]) in matched} for t in pages};keys=sorted(rm['zl'].keys()&rm['it'].keys());ev={t:[rm[t][k] for k in keys] for t in rm}
tr=rows([p for p in zltrain if p.id in train_ids]);mod=fit(tr);out={'fit_folios':len(train_ids),'reserved_folios':len(test_ids),'fit_tokens':len(tr),'matched_lines':len(matched),'both_positions':len(keys),'class_pairs_agree':sum(rm['zl'][k][-2:]==rm['it'][k][-2:] for k in keys),'raw_lines':{t:len(lines[t]) for t in lines},'raw_rows':{t:len(allrows[t]) for t in allrows},'results':{t:assess(ev[t],mod,True) for t in ev}}
by=defaultdict(list)
for r in tr:by[r[0]].append(r)
folios=sorted(by);rng=random.Random(31002);refits={t:[] for t in ev}
for rep in range(100):
 chosen=[rng.choice(folios) for f in folios];sample=[r for f in chosen for r in by[f]];m=fit(sample)
 for t in ev:refits[t].append(sum(m(r) for r in ev[t])/len(ev[t]))
for t,vals in refits.items():vals.sort();out['results'][t]['training_refit_boot_95']=[vals[2],vals[97]]
print(json.dumps(out,indent=2))
